def calculate_refund(price, days_since_purchase, is_defective):
    if days_since_purchase < 0:
        return {'status': 'error', 'refund': 0}
    elif is_defective:
        return {'status': 'refund', 'refund': price}
    elif days_since_purchase <= 7:
        return {'status': 'refund', 'refund': price}
    elif days_since_purchase <= 14:
        return {'status': 'refund', 'refund': price / 2}
    else:
        return {'status': 'refund', 'refund': 0}

