def shipping_fee(weight_kg, is_express):
    if weight_kg <= 0:
        return {'status': 'error', 'fee': 0}

    base_fee = 5.0
    additional_fee = (weight_kg - 1) * 2.0
    total_fee = base_fee + additional_fee

    if is_express:
        total_fee *= 1.5

    total_fee = min(total_fee, 40.0)

    return {'status': 'ok', 'fee': total_fee}

